/* ── Element spec (built exactly as listed) ─────────────────────────────────
   white state node fill  → CircleGeometry(0.28, 48)          #ffffff MeshBasic depthTest:false
   white state node ring  → RingGeometry(0.225, 0.28, 48)     #000000 heavy outline
   gray observation fill  → CircleGeometry(0.28, 48)          #808080
   gray observation ring  → RingGeometry(0.225, 0.28, 48)     #000000
   row horizontal edge    → CylinderGeometry(0.02,0.02,L,8)   #000000  (world +X, screen right)
   row horizontal stub    → CylinderGeometry(...)             #000000  (3.0 past column 3)
   inter-row depth edge   → CylinderGeometry(...)             #000000  (world Z = receding diagonal)
   front-row depth stub   → CylinderGeometry(...)             #000000  (1.2 toward viewer, screen down-left)
   vertical y-link stem   → CylinderGeometry(...)             #000000  (world +Y)
   labels x1..x3 / y1..y3 → addLabel, 28px bold serif, upper-right of back-row nodes
   ─────────────────────────────────────────────────────────────────────────── */

const G = {
  S: 2.6,          // lattice spacing (world units, X and Z)
  R: 0.28,         // node radius
  RIN: 0.225,      // ring inner radius (heavy stroke)
  LW: 0.02,        // edge radius (cylinder)
  GY: 1.9,         // gray node height directly above its white partner
  GZ: 0.0,         // gray node sits on the SAME vertical stem (no depth offset)
  HSTUB: 3.0,      // horizontal stub length past column 3
  DSTUB: 1.2       // front-row depth stub length toward the viewer
};
const HILITE = new THREE.Color(0x1f77b4);
const BLACK = new THREE.Color(0x000000);
const GRAYC = new THREE.Color(0x808080);
const WHITEC = new THREE.Color(0xffffff);

// front row r=0 (z = 0), back row r=2 (z = -5.2): the oblique shear sends it up-right
function siteP(r, c) { return new THREE.Vector3(c * G.S, 0, -r * G.S); }
function grayP(r, c) { return new THREE.Vector3(c * G.S, G.GY, -r * G.S + G.GZ); }
function ro(r) { return (2 - r) * 10; }   // nearer rows draw later (occlude)

const visuals = [];   // { obj, mat, group, kind, base, test }
function reg(obj, group, kind, base, test) {
  visuals.push({ obj, mat: obj.material, group, kind, base, test });
  return obj;
}

function mkMat(hex) {
  return new THREE.MeshBasicMaterial({
    color: hex, transparent: true, opacity: 1,
    depthTest: false, depthWrite: false, side: THREE.DoubleSide
  });
}
function mkDisc(pos, radius, hex, order) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(radius, 48), mkMat(hex));
  m.position.copy(pos); m.renderOrder = order; scene.add(m); return m;
}
function mkRing(pos, rin, rout, order) {
  const m = new THREE.Mesh(new THREE.RingGeometry(rin, rout, 48), mkMat(0x000000));
  m.position.copy(pos); m.renderOrder = order; scene.add(m); return m;
}
const _UPV = new THREE.Vector3(0, 1, 0);
function mkEdge(a, b, order) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(G.LW, G.LW, len, 8, 1), mkMat(0x000000));
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(_UPV, dir.clone().normalize());
  m.renderOrder = order; scene.add(m); return m;
}

const eq = (s, r, c) => !!s && s.r === r && s.c === c;
const adj = (s, r, c) => !!s && (Math.abs(s.r - r) + Math.abs(s.c - c) === 1);

/* ── grid edges (drawn first, under the nodes) ─────────────────────────── */
for (let r = 0; r < 3; r++) {
  for (let c = 0; c < 2; c++) {
    const e = mkEdge(siteP(r, c), siteP(r, c + 1), ro(r));
    reg(e, 'grid', 'edge', BLACK, s => eq(s, r, c) || eq(s, r, c + 1));
  }
  // horizontal stub running off the right-hand frame edge
  const a = siteP(r, 2), b = siteP(r, 2).add(new THREE.Vector3(G.HSTUB, 0, 0));
  reg(mkEdge(a, b, ro(r)), 'grid', 'edge', BLACK, s => eq(s, r, 2));
}
for (let c = 0; c < 3; c++) {
  for (let r = 0; r < 2; r++) {
    // depth edge to the row behind (screen: up-right / down-left)
    const e = mkEdge(siteP(r, c), siteP(r + 1, c), ro(r + 1));
    reg(e, 'grid', 'edge', BLACK, s => eq(s, r, c) || eq(s, r + 1, c));
  }
  // front-row depth stub continuing off the lower-left corner
  const a = siteP(0, c), b = siteP(0, c).add(new THREE.Vector3(0, 0, G.DSTUB));
  reg(mkEdge(a, b, ro(0)), 'grid', 'edge', BLACK, s => eq(s, 0, c));
}

/* ── vertical y-links, gray observation nodes, white state nodes ───────── */
const sites = [];
for (let r = 0; r < 3; r++) {
  sites[r] = [];
  for (let c = 0; c < 3; c++) {
    const wp = siteP(r, c), gp = grayP(r, c);
    const base = ro(r);

    const stem = mkEdge(wp.clone(), gp.clone(), base + 0);
    reg(stem, 'stem', 'edge', BLACK, s => eq(s, r, c));

    const gf = mkDisc(gp, G.R, 0x808080, base + 1);
    reg(gf, 'gray', 'fill', GRAYC, s => eq(s, r, c));
    const gr = mkRing(gp, G.RIN, G.R, base + 2);
    reg(gr, 'gray', 'ring', BLACK, s => eq(s, r, c));

    const wf = mkDisc(wp, G.R, 0xffffff, base + 3);
    const vwf = reg(wf, 'white', 'fill', WHITEC.clone(), s => eq(s, r, c) || adj(s, r, c));
    const wr = mkRing(wp, G.RIN, G.R, base + 4);
    reg(wr, 'white', 'ring', BLACK, s => eq(s, r, c) || adj(s, r, c));

    sites[r][c] = {
      r, c, p: wp, gp, fill: wf, ring: wr, grayFill: gf, grayRing: gr,
      fillVis: visuals.find(v => v.obj === vwf)
