  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
    const st = sites[r][c];
    _pv.copy(st.p).project(camera);
    const sx = (_pv.x * 0.5 + 0.5) * rect.width, sy = (-_pv.y * 0.5 + 0.5) * rect.height;
    const e = new THREE.Vector3(st.p.x + G.R, st.p.y, st.p.z).project(camera);
    const rpx = Math.abs((e.x - _pv.x) * 0.5 * rect.width);
    const dd = Math.hypot(px - sx, py - sy);
    if (dd < Math.max(rpx * 1.4, 12) && dd < bd) { bd = dd; best = st; }
  }
  return best;
}
canvas.addEventListener('pointermove', (ev) => {
  const s = pickSite(ev);
  if (s) {
    canvas.style.cursor = 'pointer';
    showTooltip('Click: Markov blanket of this state node', ev);
  } else { hideTooltip(); }
});
canvas.addEventListener('click', (ev) => {
  const s = pickSite(ev);
  if (s) { stopPlay(); setSelected(selected === s ? null : s); }
  else setSelected(null);
});

/* ── demo steps ────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The hidden lattice', layer: 'x', beta: 0.6,
    text: 'Only the white state nodes and their grid edges are shown: every site is coupled to its four nearest neighbours, and the edges run off the frame because the field is unbounded.'
  },
  {
    title: 'Per-site evidence', layer: 'y', beta: 0.6,
    text: 'Now only the vertical links appear: each gray observation y hangs off exactly one white state x, so evidence enters the model one site at a time.'
  },
  {
    title: 'Full Markov random field', layer: 'full', beta: 0.6,
    text: 'Both layers together. Click any white node to see its Markov blanket — four neighbours plus its own observation — while every other edge fades.'
  },
  {
    title: 'Weak coupling', layer: 'full', beta: 0.05,
    text: 'With β near zero each state follows its own observation independently; the shading of the white nodes is noisy and uncorrelated across the grid.'
  },
  {
    title: 'Strong coupling', layer: 'full', beta: 2.6,
    text: 'Raising β makes neighbouring white nodes converge to similar shading — the field becomes smooth — even though the gray observations never change.'
  }
];
let stepIdx = 2;
const narrTitle = document.getElementById('narrTitle');
const narrBody = document.getElementById('narrBody');
const stepInd = document.getElementById('stepInd');
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setSelected(null);
  setLayer(s.layer);
  setBeta(s.beta, false);
  narrTitle.textContent = s.title;
  narrBody.textContent = s.text;
  stepInd.textContent = (stepIdx + 1) + ' / ' + STEPS.length;
}
let playT = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playT) { clearInterval(playT); playT = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playT) { stopPlay(); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playT = setInterval(() => goToStep(stepIdx + 1), 4200);
});
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });

/* ── tween loop (opacity, colour, β) ───────────────────────────────────── */
applyShading(betaCur);
goToStep(2);

let _t0 = performance.now();
(function tween() {
  requestAnimationFrame(tween);
  const now = performance.now();
  const dt = Math.min(0.06, (now - _t0) / 1000); _t0 = now;
  const k = 1 - Math.pow(0.0015, dt);

  if (Math.abs(betaCur - betaTgt) > 0.002) {
    betaCur += (betaTgt - betaCur) * Math.min(1, k);
    betaVal.textContent = betaCur.toFixed(2);
    slider.value = betaCur;
    applyShading(betaCur);
    updateTargets();
  }
  for (const v of visuals) {
    if (v.targetOp === undefined) continue;
    v.mat.opacity += (v.targetOp - v.mat.opacity) * k;
    v.obj.visible = v.mat.opacity > 0.015;
    if (v.targetCol) v.mat.color.lerp(v.targetCol, k);
  }
  for (const l of fadeLabels) {
    if (l.targetOp === undefined) continue;
    const cur = parseFloat(l.entry.div.style.opacity || '1');
    const nv = cur + (l.targetOp - cur) * k;
    l.entry.div.style.opacity = nv.toFixed(3);
  }
})();

updateTargets();
// @FIGURE_CODE_END

