// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ─────────────────────────────────
   white state node fill  → CircleGeometry(0.42, 48)          #ffffff MeshBasic depthTest:false
   white state node ring  → RingGeometry(0.30, 0.42, 48)      #000000 heavy outline (0.12 units)
   gray observation fill  → CircleGeometry(0.42, 48)          #808080
   gray observation ring  → RingGeometry(0.30, 0.42, 48)      #000000
   row horizontal edge    → CylinderGeometry(0.038,0.038,L,8) #000000  (world +X, screen right)
   row horizontal stub R  → CylinderGeometry(...)             #000000  (2.8 past column 3)
   front-row stub L       → CylinderGeometry(...)             #000000  (1.4 left of column 1)
   inter-row depth edge   → CylinderGeometry(...)             #000000  (world Z = receding diagonal)
   front-row depth stub   → CylinderGeometry(...)             #000000  (1.6 toward viewer, down-left)
   vertical y-link stem   → CylinderGeometry(...)             #000000  (world +Y)
   labels x1..x3 / y1..y3 → addLabel, 31px bold serif, upper-right of back-row nodes
   ─────────────────────────────────────────────────────────────────────────── */

const G = {
  S: 2.6,          // lattice spacing (world units, X and Z)
  R: 0.42,         // node radius (~1.5x previous, heavy source look)
  RIN: 0.30,       // ring inner radius → 0.12 unit stroke
  LW: 0.038,       // edge radius (cylinder)
  GY: 2.2,         // gray node height directly above its white partner
  GZ: 0.30,        // gray node sits slightly behind its partner
  HSTUB: 2.8,      // horizontal stub length past column 3
  LSTUB: 1.4,      // front-row horizontal stub to the LEFT frame edge
  DSTUB: 1.6       // front-row depth stub length toward the viewer
};
const HILITE = new THREE.Color(0x1f77b4);
const BLACK = new THREE.Color(0x000000);
const GRAYC = new THREE.Color(0x808080);
const WHITEC = new THREE.Color(0xffffff);

// front row r=0 (z = 0), back row r=2 (z = -5.2): the oblique shear sends it up-right
function siteP(r, c) { return new THREE.Vector3(c * G.S, 0, -r * G.S); }
function grayP(r, c) { return new THREE.Vector3(c * G.S, G.GY, -r * G.S - G.GZ); }
function ro(r) { return (2 - r) * 10; }   // nearer rows draw later (occlude)

const visuals = [];   // { obj, mat, group, kind, base, test }
function reg(obj, group, kind, base, test) {
  visuals.push({ obj, mat: obj.material, group, kind, base, test });
  return obj;
}

function mkMat(hex) {
  return new THREE.MeshBasicMaterial({
    color: hex, transparent: true, opacity: 1,
    depthTest: false, depthWrite: false, side: THREE.DoubleSide
  });
}
function mkDisc(pos, radius, hex, order) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(radius, 48), mkMat(hex));
  m.position.copy(pos); m.renderOrder = order; scene.add(m); return m;
}
function mkRing(pos, rin, rout, order) {
  const m = new THREE.Mesh(new THREE.RingGeometry(rin, rout, 48), mkMat(0x000000));
  m.position.copy(pos); m.renderOrder = order; scene.add(m); return m;
}
const _UPV = new THREE.Vector3(0, 1, 0);
function mkEdge(a, b, order) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(G.LW, G.LW, len, 8, 1), mkMat(0x000000));
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(_UPV, dir.clone().normalize());
  m.renderOrder = order; scene.add(m); return m;
}

const eq = (s, r, c) => !!s && s.r === r && s.c === c;
const adj = (s, r, c) => !!s && (Math.abs(s.r - r) + Math.abs(s.c - c) === 1);

/* ── grid edges (drawn first, under the nodes) ─────────────────────────── */
for (let r = 0; r < 3; r++) {
  for (let c = 0; c < 2; c++) {
    const e = mkEdge(siteP(r, c), siteP(r, c + 1), ro(r));
    reg(e, 'grid', 'edge', BLACK, s => eq(s, r, c) || eq(s, r, c + 1));
  }
  // horizontal stub running off the right-hand frame edge
  const a = siteP(r, 2), b = siteP(r, 2).add(new THREE.Vector3(G.HSTUB, 0, 0));
  reg(mkEdge(a, b, ro(r)), 'grid', 'edge', BLACK, s => eq(s, r, 2));
}
// front row also continues to the LEFT frame edge (lattice unbounded both ways)
{
  const a = siteP(0, 0), b = siteP(0, 0).add(new THREE.Vector3(-G.LSTUB, 0, 0));
  reg(mkEdge(a, b, ro(0)), 'grid', 'edge', BLACK, s => eq(s, 0, 0));
}
for (let c = 0; c < 3; c++) {
  for (let r = 0; r < 2; r++) {
    // depth edge to the row behind (screen: up-right / down-left)
    const e = mkEdge(siteP(r, c), siteP(r + 1, c), ro(r + 1));
    reg(e, 'grid', 'edge', BLACK, s => eq(s, r, c) || eq(s, r + 1, c));
  }
  // front-row depth stub continuing off the lower-left corner
  const a = siteP(0, c), b = siteP(0, c).add(new THREE.Vector3(0, 0, G.DSTUB));
  reg(mkEdge(a, b, ro(0)), 'grid', 'edge', BLACK, s => eq(s, 0, c));
}

/* ── vertical y-links, gray observation nodes, white state nodes ───────── */
const sites = [];
for (let r = 0; r < 3; r++) {
  sites[r] = [];
  for (let c = 0; c < 3; c++) {
    const wp = siteP(r, c), gp = grayP(r, c);
    const base = ro(r);

    const stem = mkEdge(wp.clone(), gp.clone(), base + 0);
    reg(stem, 'stem', 'edge', BLACK, s => eq(s, r, c));

    const gf = mkDisc(gp, G.R, 0x808080, base + 1);
    reg(gf, 'gray', 'fill', GRAYC, s => eq(s, r, c));
    const gr = mkRing(gp, G.RIN, G.R, base + 2);
    reg(gr, 'gray', 'ring', BLACK, s => eq(s, r, c));

    const wf = mkDisc(wp, G.R, 0xffffff, base + 3);
    const vwf = reg(wf, 'white', 'fill', WHITEC.clone(), s => eq(s, r, c) || adj(s, r, c));
    const wr = mkRing(wp, G.RIN, G.R, base + 4);
    reg(wr, 'white', 'ring', BLACK, s => eq(s, r, c) || adj(s, r, c));

    sites[r][c] = {
      r, c, p: wp, gp, fill: wf, ring: wr, grayFill: gf, grayRing: gr,
      fillVis: visuals.find(v => v.obj === vwf)
    };
  }
}

/* ── camera: cabinet-style oblique, front-on, shear supplied by the scaffold ── */
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 48,
  depthScale: 0.58,
  axisScreenAngles: null,
  heightFraction: 0.8
});
document.getElementById('btnReset').style.display = '';

/* ── labels: all six on the back row, bold serif, upper-right of each node ── */
const SERIF = '"Times New Roman",Times,serif';
function labHTML(sym, sub) {
  return '<span style="font-family:' + SERIF + ';font-weight:700;">' + sym +
    '<sub style="font-weight:400;font-size:0.66em;">' + sub + '</sub></span>';
}
const fadeLabels = [];   // { entry, group, test, targetOp }
for (let c = 0; c < 3; c++) {
  const wp = siteP(2, c), gp = grayP(2, c);
  const ex = addLabel(labHTML('x', c + 1), wp,
    { fontSize: '31px', color: '#000', offset: [46, -34] });
  fadeLabels.push({ entry: ex, group: 'white', test: (s => eq(s, 2, c) || adj(s, 2, c)) });

  const ey = addLabel(labHTML('y', c + 1), gp,
    { fontSize: '31px', color: '#000', offset: [46, -36] });
  fadeLabels.push({ entry: ey, group: 'gray', test: (s => eq(s, 2, c)) });
}
fadeLabels.forEach(l => { l.entry.div.style.opacity = '1'; });

/* ── observations + mean-field smoothing (coupling slider) ─────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const _rnd = mulberry32(20260923);
const OBS = [];
for (let r = 0; r < 3; r++) { OBS[r] = []; for (let c = 0; c < 3; c++) OBS[r][c] = _rnd(); }

const NB = [[1, 0], [-1, 0], [0, 1], [0, -1]];
function solveStates(beta) {
  const s = OBS.map(row => row.slice());
  for (let it = 0; it < 120; it++) {
    for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
      let sum = 0, n = 0;
      for (const [dr, dc] of NB) {
        const rr = r + dr, cc = c + dc;
        if (rr >= 0 && rr < 3 && cc >= 0 && cc < 3) { sum += s[rr][cc]; n++; }
      }
      s[r][c] = (OBS[r][c] + beta * sum) / (1 + beta * n);
    }
  }
  return s;
}
// Pure-white by default (matches the printed figure). Shading is an OPT-IN cue
// used by the coupling demo / checkbox only.
let shadingOn = false;
function applyShading(beta) {
  if (!shadingOn) {
    for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++)
      sites[r][c].fillVis.base = WHITEC.clone();
    return;
  }
  const s = solveStates(beta);
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
    const L = 0.62 + 0.38 * Math.max(0, Math.min(1, s[r][c]));
    sites[r][c].fillVis.base = new THREE.Color(L, L, L);
  }
}

/* ── layer / selection state ───────────────────────────────────────────── */
const LAYER_OP = {
  x: { grid: 1, stem: 0, gray: 0, white: 1 },
  y: { grid: 0, stem: 1, gray: 1, white: 1 },
  full: { grid: 1, stem: 1, gray: 1, white: 1 }
};
let viewLayer = 'full';
let selected = null;

function updateTargets() {
  const L = LAYER_OP[viewLayer];
  for (const v of visuals) {
    const lo = L[v.group];
    const inB = selected ? v.test(selected) : true;
    let op = lo * (selected && !inB ? 0.12 : 1);
    if (v.group === 'white' && v.kind === 'fill') op = lo;   // keep white discs as occluders
    v.targetOp = op;
    const hi = selected && inB && v.kind !== 'fill';
    v.targetCol = (v.kind === 'fill') ? v.base : (hi ? HILITE : v.base);
  }
  for (const l of fadeLabels) {
    const lo = L[l.group];
    const inB = selected ? l.test(selected) : true;
    l.targetOp = lo * (selected && !inB ? 0.18 : 1);
  }
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
    const sel = selected && selected.r === r && selected.c === c;
    sites[r][c].ring.scale.setScalar(sel ? 1.18 : 1);
  }
}

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const layerBtns = Array.from(document.querySelectorAll('.layerBtn'));
function setLayer(key) {
  viewLayer = key;
  layerBtns.forEach(b => b.classList.toggle('active', b.dataset.v === key));
  updateTargets();
}
layerBtns.forEach(b => b.addEventListener('click', () => { stopPlay(); setLayer(b.dataset.v); }));

const slider = document.getElementById('coupling');
const betaVal = document.getElementById('betaVal');
const chkShade = document.getElementById('chkShade');
let betaCur = 0.6, betaTgt = 0.6;
function setBeta(v, instant) {
  betaTgt = v;
  if (instant) { betaCur = v; slider.value = v; }
  betaVal.textContent = Number(instant ? v : betaCur).toFixed(2);
}
slider.addEventListener('input', () => {
  stopPlay();
  if (!chkShade.checked) { chkShade.checked = true; shadingOn = true; }
  setBeta(parseFloat(slider.value), true);
  applyShading(betaCur); updateTargets();
});
chkShade.addEventListener('change', () => {
  stopPlay();
  shadingOn = chkShade.checked;
  applyShading(betaCur); updateTargets();
});

const selInfo = document.getElementById('selInfo');
function setSelected(s) {
  selected = s;
  if (!s) selInfo.textContent = '';
  else {
    let n = 0;
    for (const [dr, dc] of NB) {
      const rr = s.r + dr, cc = s.c + dc;
      if (rr >= 0 && rr < 3 && cc >= 0 && cc < 3) n++;
    }
    const nm = (s.r === 2) ? ('x<sub>' + (s.c + 1) + '</sub>')
      : ('the site in column ' + (s.c + 1) + ', row ' + (3 - s.r) + ' from the back');
    selInfo.innerHTML = 'Markov blanket of <b>' + nm + '</b>: its four lattice neighbours (' +
      n + ' drawn here, the rest continue off-frame) plus its own observation <b>y</b>. ' +
      'Conditioned on these, it is independent of the whole remaining field.';
  }
  updateTargets();
}
document.getElementById('btnClearSel').addEventListener('click', () => setSelected(null));

/* ── click / hover picking on the white nodes (projection-aware) ───────── */
const _pv = new THREE.Vector3();
function pickSite(ev) {
  const rect = canvas.getBoundingClientRect();
  const px = ev.clientX - rect.left, py = ev.clientY - rect.top;
  let best = null, bd = 1e9;
  for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) {
    const st = sites[r][c];
    _pv.copy(st.p).project(camera);
    const sx = (_pv.x * 0.5 + 0.5) * rect.width, sy = (-_pv.y * 0.5 + 0.5) * rect.height;
    const e = new THREE.Vector3(st.p.x + G.R, st.p.y, st.p.z).project(camera);
    const rpx = Math.abs((e.x - _pv.x) * 0.5 * rect.width);
    const dd = Math.hypot(px - sx, py - sy);
    if (dd < Math.max(rpx * 1.3, 12) && dd < bd) { bd = dd; best = st; }
  }
  return best;
}
canvas.addEventListener('pointermove', (ev) => {
  const s = pickSite(ev);
  if (s) {
    canvas.style.cursor = 'pointer';
    showTooltip('Click: Markov blanket of this state node', ev);
  } else { hideTooltip(); }
});
canvas.addEventListener('click', (ev) => {
  const s = pickSite(ev);
  if (s) { stopPlay(); setSelected(selected === s ? null : s); }
  else setSelected(null);
});

/* ── demo steps ────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The hidden lattice', layer: 'x', beta: 0.6, shade: false,
    text: 'Only the white state nodes and their grid edges are shown: every site is coupled to its four nearest neighbours, and the edges run off the frame because the field is unbounded.'
  },
  {
    title: 'Per-site evidence', layer: 'y', beta: 0.6, shade: false,
    text: 'Now only the vertical links appear: each gray observation y hangs off exactly one white state x, so evidence enters the model one site at a time.'
  },
  {
    title: 'Full Markov random field', layer: 'full', beta: 0.6, shade: false,
    text: 'Both layers together. Click any white node to see its Markov blanket — four neighbours plus its own observation — while every other edge fades.'
  },
  {
    title: 'Weak coupling', layer: 'full', beta: 0.05, shade: true,
    text: 'Shading now shows each state value. With β near zero each state follows its own observation independently; the shading is noisy and uncorrelated across the grid.'
  },
  {
    title: 'Strong coupling', layer: 'full', beta: 2.6, shade: true,
    text: 'Raising β makes neighbouring states converge to similar shading — the field becomes smooth — even though the gray observations never change.'
  }
];
let stepIdx = 2;
const narrTitle = document.getElementById('narrTitle');
const narrBody = document.getElementById('narrBody');
const stepInd = document.getElementById('stepInd');
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setSelected(null);
  setLayer(s.layer);
  shadingOn = !!s.shade;
  chkShade.checked = shadingOn;
  setBeta(s.beta, false);
  applyShading(betaCur);
  narrTitle.textContent = s.title;
  narrBody.textContent = s.text;
  stepInd.textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  updateTargets();
}
let playT = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playT) { clearInterval(playT); playT = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playT) { stopPlay(); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playT = setInterval(() => goToStep(stepIdx + 1), 4200);
});
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });

/* ── tween loop (opacity, colour, β) ───────────────────────────────────── */
applyShading(betaCur);
goToStep(2);

let _t0 = performance.now();
(function tween() {
  requestAnimationFrame(tween);
  const now = performance.now();
  const dt = Math.min(0.06, (now - _t0) / 1000); _t0 = now;
  const k = 1 - Math.pow(0.0015, dt);

  if (Math.abs(betaCur - betaTgt) > 0.002) {
    betaCur += (betaTgt - betaCur) * Math.min(1, k);
    betaVal.textContent = betaCur.toFixed(2);
    slider.value = betaCur;
    applyShading(betaCur);
    updateTargets();
  }
  for (const v of visuals) {
    if (v.targetOp === undefined) continue;
    v.mat.opacity += (v.targetOp - v.mat.opacity) * k;
    v.obj.visible = v.mat.opacity > 0.015;
    if (v.targetCol) v.mat.color.lerp(v.targetCol, k);
  }
  for (const l of fadeLabels) {
    if (l.targetOp === undefined) continue;
    const cur = parseFloat(l.entry.div.style.opacity || '1');
    const nv = cur + (l.targetOp - cur) * k;
    l.entry.div.style.opacity = nv.toFixed(3);
  }
})();

updateTargets();
